    static void emptyThenRefill(){for(String source:List.of("attack","item","supporter","ability"))for(int n:List.of(0,1,8,9)){var m=game(MILL+","+SHUFFLE,"NORMAL");rig(m,B,CARD);CardInstance played=Set.of("item","supporter").contains(source)?obtain(m,A,source):null;size(m,A,0);var hand=zone(m,A,"hand");var retained=new ArrayList<CardInstance>();if(played!=null)retained.add(played);for(var c:List.copyOf(hand))if(retained.size()<n+(played==null?0:1)&&!retained.contains(c))retained.add(c);for(var c:List.copyOf(hand))if(!retained.contains(c)){hand.remove(c);zone(m,A,"discard").add(c);}var refill=retained.stream().filter(c->!c.equals(played)).toList();var old=m.privateView(A).discard();if(source.equals("attack"))m.attack(A,"fixture-mill");else if(source.equals("ability"))m.useAbility(A,active(m,A),"fixture-ability");else m.playTrainer(A,played.instanceId(),null);drain(m);check(m.privateView(A).deck().size()==Math.max(0,n-8)&&m.privateView(A).hand().isEmpty()&&m.phase()==MatchPhase.TURN,"Empty-at-capture event lost or refilled-deck mill wrong: "+source+"/"+n);var moved=new ArrayList<>(m.privateView(A).discard());moved.removeAll(old);if(played!=null){check(moved.remove(played),"Resolving Trainer was shuffled/lost");}check(moved.size()==Math.min(8,n)&&refill.containsAll(moved),"Refill physical card conservation");}}
